def test_merging_zero_shards_or_all_empty_shards_is_the_zero_fact(self):
    chart = make_chart()
    # Several "shards" that are all empty must merge to the zero fact.
    shards = [post_vouchers(BASE, copy.deepcopy(chart), [])
              for _ in range(4)]
    full = post_vouchers(BASE, chart, make_batch())
    merged = {r["code"]: [0, 0] for r in shards[0]["accounts"]}
    for result in shards:
        for row in result["accounts"]:
            merged[row["code"]][0] += to_cents(row["debit_turnover"])
            merged[row["code"]][1] += to_cents(row["credit_turnover"])
    for row in full["accounts"]:
        # Empty-shard merge is zero, and zero is the empty-batch fact;
        # non-empty full batch deliberately differs somewhere.
        self.assertEqual(merged[row["code"]], [0, 0])

